253	    /**
254	     * Count the existing owners that already share the given first and last name,
255	     * compared case-insensitively. Used to stamp a new owner's namesake count at
256	     * registration, before it is itself persisted.
257	     */
258	    private int countNamesakes(String firstName, String lastName) {
259	        return (int) ownerRepository.findByLastNameIgnoreCase(lastName).stream()
260	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName))
261	            .count();
262	    }
